import{c as n,Z as o,Q as l,j as t,g as a,n as r,o as s,m as d}from"./chunks/framework.BPKcPtvA.js";const k=JSON.parse('{"title":"Changelog","description":"","frontmatter":{"title":"Changelog"},"headers":[],"relativePath":"en/changelog.md","filePath":"en/changelog.md","lastUpdated":1794895051000}'),c={name:"en/changelog.md"};function u(h,e,p,g,m,f){const i=o("ReleaseHistory");return l(),t("div",null,[e[0]||(e[0]=a("h1",{id:"changelog",tabindex:"-1"},[r("Changelog "),a("a",{class:"header-anchor",href:"#changelog","aria-label":'Permalink to "Changelog"'},"​")],-1)),s(i,{lang:"en"}),e[1]||(e[1]=d('<h2 id="_3-0-0-2026-11-15" tabindex="-1">3.0.0 (2026-11-15) <a class="header-anchor" href="#_3-0-0-2026-11-15" aria-label="Permalink to &quot;3.0.0 (2026-11-15)&quot;">​</a></h2><p>3.0.0 is a major release for both the interface and the packaging pipeline. The launcher is now fully implemented on Qt Quick / QML, and the existing version management, resources and modpacks, servers, multiplayer, backups, music, AGENT, voice, achievements, plugins and Bedrock Edition features were carried over into the new interface structure.</p><h3 id="a-brand-new-qt-quick-interface" tabindex="-1">A brand-new Qt Quick interface <a class="header-anchor" href="#a-brand-new-qt-quick-interface" aria-label="Permalink to &quot;A brand-new Qt Quick interface&quot;">​</a></h3><ul><li>Windows, navigation, pages, dialogs and overlays were rebuilt with QML and FluentUI.</li><li>Primary navigation is grouped into Game / Resources &amp; Multiplayer / Tools &amp; Extensions, with breadcrumbs, a page stack and <code>fmcl://</code> deep links.</li><li>All 12 feature domains share one page skeleton with <code>ready / loading / empty / error</code> states; switching pages, themes or languages no longer rebuilds the whole window.</li><li>The five themes, custom accent colour, version-driven theme and runtime language switching all remain available.</li><li>The splash screen, terms and announcement flow and the main window fallback are managed by the startup controller.</li></ul><h3 id="versions-resources-and-servers" tabindex="-1">Versions, resources and servers <a class="header-anchor" href="#versions-resources-and-servers" aria-label="Permalink to &quot;Versions, resources and servers&quot;">​</a></h3><ul><li>Vanilla plus eight mod loaders, with detection for nine loaders, renaming, verification and deletion.</li><li>Modrinth and CurseForge browsing, dependency installation, detail pages and batch updates.</li><li>Six client modpack sources, plus <code>.mrpack</code> server hosting.</li><li>Server installation, startup, console, per-server memory, automatic port conflict handling, a visual <code>server.properties</code> editor and server-side mod and resource pack management.</li><li>EasyTier Terracotta multiplayer, plus manual and automatic world backups with verification, restore and export.</li><li>Bedrock Edition UWP / GDK download, install and launch, Windows 10 19041 or later only.</li></ul><h3 id="music-agent-and-plugins" tabindex="-1">Music, AGENT and plugins <a class="header-anchor" href="#music-agent-and-plugins" aria-label="Permalink to &quot;Music, AGENT and plugins&quot;">​</a></h3><ul><li>The music page was rebuilt: discovery home, five online sources with Bilibili fallback, playlists, lyrics, desktop lyrics, play queue and global hotkeys.</li><li>Windows SMTC media control, media keys and progress sync.</li><li>AGENT supports multiple providers, 33 tools, three permission levels, Skills, streaming output and tool confirmation.</li><li>SenseVoice offline voice input, with model download and local ZIP import.</li><li>New plugin manager, plugin marketplace and the QML page extension protocol <code>ui_api: 2</code>.</li><li>Plugin pages can register into primary navigation, fetch data with <code>Plugins.call</code> and push refreshes with <code>emit_ui_event</code>.</li></ul><h3 id="packaging-and-installation" tabindex="-1">Packaging and installation <a class="header-anchor" href="#packaging-and-installation" aria-label="Permalink to &quot;Packaging and installation&quot;">​</a></h3><ul><li>Windows ships an x64 NSIS installer that installs per user and needs no administrator rights.</li><li>Linux ships an x86_64 directory tarball, installable from source or tarball via <code>scripts/install.sh</code>.</li><li>The installer now includes the FluentUI QML plugin DLL, fixing the &quot;QML root object could not be created&quot; error after installation.</li><li>Windows build log encoding, Linux Qt plugin lookup, artifact manifests and CUPS dependencies were fixed.</li></ul><h3 id="upgrade-notes" tabindex="-1">Upgrade notes <a class="header-anchor" href="#upgrade-notes" aria-label="Permalink to &quot;Upgrade notes&quot;">​</a></h3><ul><li>You can install 3.0.0 directly; the install directory and user data paths are unchanged, and uninstalling never deletes user data recursively.</li><li>Back up <code>config.json</code>, <code>accounts.json</code>, <code>.minecraft</code> and the music data directory before upgrading.</li><li>To roll back, uninstall 3.0.0 and install 2.12.6.</li><li>32-bit Windows is no longer published for 3.0.0; keep using 2.12.6 there.</li><li>The CustomTkinter interface and the <code>ui_backend</code> switch were removed. Only the QML interface remains; the command line mode is still available in <code>main.py</code>.</li><li>Plugins declaring <code>ui_api: 1</code> no longer load their UI pages, while non-UI hooks keep working. QML pages must use <code>ui_api: 2</code> and <code>ui.page.register</code>.</li><li>The standalone <code>FMCL-Agent.exe</code> is no longer bundled; use <code>python main.py -A</code> or <code>python main.py --agent &quot;instruction&quot;</code> instead.</li></ul><h3 id="known-limitations" tabindex="-1">Known limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known limitations&quot;">​</a></h3><ul><li>No <code>.dmg</code> or binary build for macOS yet; running from source is supported.</li><li>Linux builds are x86_64 only; there is no ARM64 binary yet.</li><li>Global hotkeys may not work for non-root Linux users; other features are unaffected.</li><li>Online music and resource search depend on third-party APIs, so a source may be temporarily unavailable.</li><li>GDK Bedrock Edition may require the .NET 10 SDK on first use; the lite installer does not bundle it.</li></ul>',14))])}const w=n(c,[["render",u]]);export{k as __pageData,w as default};
